-- 2026-08-15 八行业企业转型金融评估数据迁移脚本

-- 执行前请确认 financial_institution 中已经存在银行A、银行B、银行C。

set names utf8mb4;

drop table if exists `electric_company_data`;

drop table if exists `nonferrous_metal_company_data`;
create table `nonferrous_metal_company_data` (
  `id` bigint primary key auto_increment comment '数据ID',
  `institution_code` varchar(64) null comment '所属金融机构编码',
  `institution_name` varchar(200) null comment '金融机构名称',
  `industry_name` varchar(100) null comment '行业',
  `company_name` varchar(200) null comment '企业名称',
  `stock_code` varchar(20) null comment '股票代码',
  `company_type` varchar(100) null comment '企业类型',
  `data_year` int null comment '年份',
  `transition_target_commitment` tinyint null comment '是否具有转型目标与承诺',
  `transition_strategy_path` tinyint null comment '是否具有转型战略与路径规划',
  `governance_incentive` tinyint null comment '是否具有治理架构与激励',
  `transition_technology_application` tinyint null comment '是否具有转型技术应用现状',
  `carbon_asset_management` tinyint null comment '是否具有碳资产管理能力',
  `risk_management_market_opportunity` tinyint null comment '是否具有风险管理与市场机遇',
  `information_disclosure_transparency` tinyint null comment '是否具有信息披露与透明度',
  `just_transition` tinyint null comment '是否具有公正转型',
  `environmental_compliance` tinyint null comment '是否环境合规',
  `operating_revenue` decimal(18,4) null comment '营业收入，单位亿元',
  `net_profit` decimal(18,4) null comment '净利润，单位亿元',
  `r_and_d_expense` decimal(18,4) null comment '研发费用，单位亿元',
  `asset_liability_ratio` decimal(18,4) null comment '资产负债率',
  `sales_net_profit_margin` decimal(18,4) null comment '销售净利率',
  `revenue_growth_rate` decimal(18,4) null comment '营业收入增长率',
  `r_and_d_intensity` decimal(18,4) null comment '研发投入强度',
  `operation_quality_score` decimal(18,4) null comment '企业经营质量评分',
  `electrolytic_aluminum_renewable_power_ratio` decimal(18,4) null comment '电解铝使用可再生能源绿电比例',
  `electrolytic_aluminum_dc_power_consumption` decimal(18,4) null comment '电解铝铝液直流电耗',
  `recycled_metal_supply_ratio` decimal(18,4) null comment '再生金属供应占比',
  `recycled_aluminum_output` decimal(18,4) null comment '再生铝产量',
  `aluminum_carbon_emission_intensity` decimal(18,4) null comment '吨铝碳排放强度',
  `molten_aluminum_direct_alloying_ratio` decimal(18,4) null comment '铝水直接合金化比例',
  `environmental_performance_rating` varchar(30) null comment '环保绩效评级',
  `transition_score` decimal(18,4) null comment '转型综合评分',
  `green_loan_score` decimal(18,4) null comment '绿色贷款评分',
  `green_loan` tinyint null comment '目标变量：是否绿色贷款',
  `verified_transition_performance` tinyint null comment '目标变量：经核验转型绩效',
  key `idx_institution_year` (`institution_code`, `data_year`),
  key `idx_company_name` (`company_name`),
  key `idx_green_loan` (`green_loan`),
  key `idx_verified_transition_performance` (`verified_transition_performance`)
) engine=InnoDB default charset=utf8mb4 comment='有色金属行业企业转型金融评估数据表';


update `nonferrous_metal_company_data` data_row join `financial_institution` institution on data_row.`institution_name` = institution.`institution_name` set data_row.`institution_code` = institution.`institution_code`;

